const raw = $input.first().json.choices[0].message.content;
const cleaned = raw.replace(/```json/gi, '').replace(/```/g, '').trim();
let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (err) {
  return [{ json: { _valid: false, _raw: cleaned, _error: err.message } }];
}
return [{ json: { _valid: true, generation_run_id: $('Set Business Context').first().json.generation_run_id, agent: 'positioning', positioning_output: parsed } }];

const raw = $input.first().json.choices[0].message.content;
const cleaned = raw.replace(/```json/gi, '').replace(/```/g, '').trim();
let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (err) {
  return [{ json: { _valid: false, _raw: cleaned, _error: err.message } }];
}
return [{ json: { _valid: true, generation_run_id: $('Set Business Context').first().json.generation_run_id, agent: 'icp', icp_output: parsed } }];

const body = $input.first().json.body || {};
const required = ['company_name', 'core_customer_problem'];
const missing = required.filter(f => !body[f] || String(body[f]).trim() === '');

if (missing.length > 0) {
  return [{ json: { _valid: false, _error: 'Missing required fields: ' + missing.join(', ') } }];
}
return [{ json: { ...$input.first().json, _valid: true } }];

const d = $('Set Business Context').first().json;
const marketingStage = d.marketing_stage || 'Brand Awareness (Top of Funnel)';

const positioningBody = {
  model: 'deepseek/deepseek-v4-flash',
  temperature: 0.2,
  top_p: 0.1,
  response_format: { type: 'json_object' },
  provider: { order: ['Together', 'AtlasCloud', 'Venice'], allow_fallbacks: true },
  messages: [
    {
      role: 'system',
      content: 'You are an elite B2B product positioning strategist. Output ONLY valid JSON. SCHEMA: {"category_definition":"string under 12 words","positioning_statement":"For [target customer] who [specific problem], [company] is the [category] that [unique benefit], unlike [main alternative] which [key weakness]","differentiation_pillars":["exactly 3 strings each stating a distinct competitive strength of the company, framed as what the company does uniquely well — not what competitors do poorly. Each pillar must start with the company name or a capability it owns."],"market_framing_strategy":"one sentence under 25 words usable verbatim in a sales email"}'
    },
    {
      role: 'user',
      content: 'Generate positioning for this company only. Company: ' + d.company_name + ' Product: ' + d.product_description + ' Target audience: ' + d.target_audience + ' Competitors: ' + d.primary_competitors + ' Customer problem: ' + d.core_customer_problem + ' Desired outcome: ' + d.desired_outcome + ' Business model: ' + d.business_model + ' Unique differentiators: ' + d.unique_differentiators + ' Marketing stage: ' + marketingStage + ' Return JSON with category_definition, positioning_statement, differentiation_pillars, market_framing_strategy.'
    }
  ]
};

const icpBody = {
  model: 'deepseek/deepseek-v4-flash',
  temperature: 0.2,
  top_p: 0.1,
  response_format: { type: 'json_object' },
  provider: { order: ['Together', 'AtlasCloud', 'Venice'], allow_fallbacks: true },
  messages: [
    {
      role: 'system',
      content: 'You are an elite B2B customer intelligence analyst. Output ONLY valid JSON. SCHEMA: {"primary_target_persona":"string including specific age range (e.g. 28-45), job title, company size, and seniority level","adoption_pattern":"string explaining top-down or bottom-up and why","buying_triggers":["exactly 5 specific observable events that move someone from passive to actively shopping"],"customer_fears_and_risks":["exactly 3 product-specific fears"],"economic_buyer_profile":"string with exact title, company size range, annual budget authority in dollars"}. IMPORTANT: Do not default to enterprise buyers. Match the ICP to the actual business model and target audience provided. If the product targets prosumers, SMBs, or individual professionals, reflect that accurately. Always include a specific age range in the primary_target_persona. Do NOT use generic placeholder titles like IT Project Manager, Business Analyst, or Operations Manager unless the product description explicitly names those roles as the target user.'
    },
    {
      role: 'user',
      content: 'Generate ICP for this company only. Company: ' + d.company_name + ' Product: ' + d.product_description + ' Target audience: ' + d.target_audience + ' Competitors: ' + d.primary_competitors + ' Customer problem: ' + d.core_customer_problem + ' Business model: ' + d.business_model + ' Unique differentiators: ' + d.unique_differentiators + ' Marketing stage: ' + marketingStage + ' IMPORTANT: The ICP must reflect ALL segments of the target audience provided, not just enterprise buyers. Include a specific age range (e.g. 28-45) in the persona. Include exact budget figures in the economic buyer profile. Return JSON with primary_target_persona, adoption_pattern, buying_triggers array of exactly 5, customer_fears_and_risks array of exactly 3, economic_buyer_profile.'
    }
  ]
};

return [{
  json: {
    generation_run_id: d.generation_run_id,
    company_name: d.company_name,
    marketing_stage: marketingStage,
    positioning_body: positioningBody,
    icp_body: icpBody
  }
}];
